const API_BASE=window.SHUUD_API_BASE||"/api/v1/shuud";
const CASE_KEY="shuud:lastCase";
const steps=["incident","evidence","decision","insurance","escrow","release","clearance","summary"];
const stepEls=[...document.querySelectorAll(".flow-step")];
const checks=["Даатгал хүчинтэй","Хоёр тал зөвшөөрсөн","Хүний гэмтэлгүй","Гуравдагч этгээдийн хохиролгүй","Маргаангүй","Залилангийн дохиогүй","Нотлох материал бүрэн","Хохирол ≤ ₮2,000,000"];
const checksEl=document.getElementById("checks"),logEl=document.getElementById("log"),runBtn=document.getElementById("runCase");
checksEl.innerHTML=checks.map(x=>`<div class="check"><span>${x}</span><b class="ok">PASS</b></div>`).join("");
let seconds=0,timer=null,pollTimer=null,currentIncidentId=null;
function setStep(s){const i=steps.indexOf(s);stepEls.forEach((e,n)=>{e.classList.toggle("active",n===i);e.classList.toggle("done",n<i)})}
function completeSteps(){stepEls.forEach(e=>{e.classList.remove("active");e.classList.add("done")})}
function renderElapsed(v){const n=Math.max(0,Math.round(Number(v)||0));document.getElementById("elapsed").textContent=`${String(Math.floor(n/60)).padStart(2,"0")}:${String(n%60).padStart(2,"0")}`;document.getElementById("meterFill").style.width=`${Math.min(n/120*100,100)}%`}
function logEvent(m,s="PASS"){const r=document.createElement("div");r.className="check";r.innerHTML=`<span>${m}</span><b class="ok">${s}</b>`;logEl.prepend(r)}
async function api(p,o={}){const r=await fetch(API_BASE+p,{...o,headers:{"content-type":"application/json",...(o.headers||{})}});const b=await r.json().catch(()=>({}));if(!r.ok)throw Error(`${r.status}: ${b.detail||r.statusText}`);return b}
function reset(){clearInterval(timer);seconds=0;renderElapsed(0);setStep("incident");logEl.innerHTML="";["incidentValue","decisionValue","escrowValue","providerValue","savedValue","clearanceValue"].forEach(id=>document.getElementById(id).textContent="—");document.getElementById("incidentLabel").textContent="—";document.getElementById("systemStatus").textContent="RUNNING";document.getElementById("kpiBadge").textContent="LIVE"}
function renderCase(c){if(!c||!c.incident_id)return;currentIncidentId=c.incident_id;document.getElementById("incidentValue").textContent=c.incident_id;document.getElementById("incidentLabel").textContent=`Incident: ${c.incident_id}`;document.getElementById("decisionValue").textContent=c.decision||"—";document.getElementById("providerValue").textContent=c.provider||"NEF";document.getElementById("escrowValue").textContent=c.payment==="RELEASED"?"RELEASED":(c.escrow_id?"LOCKED":"—");if(c.economic_savings_mnt!=null)document.getElementById("savedValue").textContent=`${Math.round(Number(c.economic_savings_mnt)).toLocaleString("mn-MN")} MNT`;if(c.clearance_seconds!=null){renderElapsed(c.clearance_seconds);document.getElementById("clearanceValue").textContent=`${Number(c.clearance_seconds).toFixed(1)} сек`}const order=["incident","evidence","decision","insurance","escrow","release","clearance"];const idx=Math.max(0,order.indexOf(c.state));if(c.state==="complete"){completeSteps();document.getElementById("systemStatus").textContent="CASE COMPLETE";document.getElementById("kpiBadge").textContent="PASS ≤ 120s";clearInterval(timer);stopPolling()}else{setStep(order[idx]||"incident");document.getElementById("systemStatus").textContent="CASE LIVE";document.getElementById("kpiBadge").textContent="LIVE CASE"}logEl.innerHTML="";const labels={incident:"Бүртгэл: кейс бүртгэгдсэн",evidence:"Баталгаажуулалт: зураг, байршил, хоёр талын зөвшөөрөл",decision:`SHIID: ${c.decision||"—"}`,insurance:c.insurance?"Даатгал: хүчинтэй · эх үүсвэр баталгаажсан":"Даатгал: шалгаж байна",escrow:"Эскроу: эх үүсвэр түгжигдсэн",release:"Төлбөр: RELEASED · баталгаажсан",clearance:`Зам чөлөөлөлт: ${c.clearance_seconds!=null?Number(c.clearance_seconds).toFixed(1)+" сек":"бүртгэгдэж байна"}`};const count=c.state==="complete"?7:Math.max(0,idx);order.slice(0,count+1).forEach(k=>logEvent(labels[k]));if(c.state==="complete")logEvent(`Эдийн засгийн үр нөлөө: ${Math.round(Number(c.economic_savings_mnt||0)).toLocaleString("mn-MN")} MNT хэмнэлт`)}
async function refreshRemote(id){try{const c=await api(`/incidents/${encodeURIComponent(id)}`);renderCase(c);return c}catch(e){if(e.message.startsWith("404"))return null;console.warn("SHUUD case refresh failed",e);return null}}
function startPolling(id){stopPolling();currentIncidentId=id;refreshRemote(id);pollTimer=setInterval(()=>refreshRemote(id),2000)}
function stopPolling(){if(pollTimer){clearInterval(pollTimer);pollTimer=null}}
async function loadStored(){let c=null;try{c=JSON.parse(localStorage.getItem(CASE_KEY)||"null")}catch(_){}const q=new URLSearchParams(location.search).get("incident_id");const id=q||(c&&c.incident_id);if(id){if(c&&c.incident_id===id)renderCase(c);startPolling(id)}}
async function runCase(){runBtn.disabled=true;stopPolling();reset();timer=setInterval(()=>{seconds++;renderElapsed(seconds)},1000);try{const incident=await api("/incidents",{method:"POST",body:JSON.stringify({location:"СБД / Энхтайвны өргөн чөлөө",vehicle_a:"UB-TEST-A",vehicle_b:"UB-TEST-B",description:"SHUUD minor incident — хүний гэмтэлгүй, маргаангүй"})});const id=incident.incident_id;currentIncidentId=id;document.getElementById("incidentValue").textContent=id;document.getElementById("incidentLabel").textContent=`Incident: ${id}`;logEvent(`Бүртгэл: ${id} үүсэв`);const ref=`OPERATOR-${id}`;await api("/evidence",{method:"POST",body:JSON.stringify({incident_id:id,evidence_refs:[ref],gps_coordinates:"47.9184,106.9177",captured_at:new Date().toISOString(),vehicle_identity_refs:["UB-TEST-A","UB-TEST-B"],consent_refs:["CONSENT-A","CONSENT-B"],media_complete:true})});setStep("evidence");logEvent("Баримт, байршил, хоёр талын зөвшөөрөл баталгаажив");const d=await api("/decisions",{method:"POST",body:JSON.stringify({incident_id:id,evidence_refs:[ref],damage_estimate_mnt:500000,two_party_consent:"PASS",vehicle_identity_verified:"PASS",timestamp_location_verified:"PASS",media_complete:"PASS",no_injury:"PASS",no_third_party_property_damage:"PASS",dispute_present:"PASS",fraud_flag:"PASS",insurance_valid:"PASS",beneficiary_valid:"PASS",witness_verified:"PASS"})});setStep("decision");document.getElementById("decisionValue").textContent=d.decision;logEvent(`SHIID: ${d.decision} · дүрэм ${d.rule_version}`);if(d.decision!=="APPROVE")throw Error(`SHIID ${d.decision}`);setStep("insurance");logEvent("Даатгал: хүчинтэй · эх үүсвэр баталгаажив");const eid=`OPERATOR-ESCROW-${id}`;const e=await api("/escrows",{method:"POST",body:JSON.stringify({incident_id:id,escrow_id:eid,amount_mnt:500000,settlement_provider:"NEF"})});setStep("escrow");document.getElementById("escrowValue").textContent=e.state;document.getElementById("providerValue").textContent="NEF";logEvent(`Эскроу: ₮500,000 · ${e.state}`);const rel=await api("/release",{method:"POST",body:JSON.stringify({incident_id:id,escrow_id:eid})});setStep("release");document.getElementById("escrowValue").textContent=rel.new_state;logEvent(`Төлбөр: ${rel.new_state}`);const cl=await api("/metrics/clearance",{method:"POST",body:JSON.stringify({incident_id:id})});seconds=Math.round(cl.elapsed_seconds);renderElapsed(seconds);setStep("clearance");document.getElementById("clearanceValue").textContent=`${seconds} сек`;logEvent(`Зам чөлөөлөлт: ${seconds} сек`,cl.within_two_minutes?"PASS":"WARN");const s=await api(`/metrics/${encodeURIComponent(id)}/summary`,{method:"POST",body:JSON.stringify({baseline_seconds:600,affected_vehicles:2,vehicle_value_per_minute_mnt:1000,insurer_cost_per_minute_mnt:500,public_road_cost_per_minute_mnt:800})});setStep("summary");document.getElementById("savedValue").textContent=`${s.economic_impact.total_savings_mnt} MNT`;clearInterval(timer);document.getElementById("kpiBadge").textContent=cl.within_two_minutes?"PASS ≤ 120s":"OVER 120s";document.getElementById("systemStatus").textContent="CASE COMPLETE";logEvent(`Эдийн засгийн үр нөлөө: ${s.economic_impact.total_savings_mnt} MNT хэмнэлт`);startPolling(id)}catch(e){clearInterval(timer);document.getElementById("kpiBadge").textContent="ERROR";document.getElementById("systemStatus").textContent="SANDBOX ERROR";logEvent(e.message,"ERROR");console.error(e)}finally{runBtn.disabled=false}}
runBtn.addEventListener("click",runCase);window.addEventListener("storage",e=>{if(e.key===CASE_KEY&&e.newValue)try{renderCase(JSON.parse(e.newValue))}catch(_){}});loadStored();